#include "darc.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <dirent.h>

static int entcmp(const void*a,const void*b){const DarcRhEnt*x=a,*y=b;return darc_cid_cmp(&x->cid,&y->cid);}
static int read_header_fd(const char*path,DarcRhEnt*out){uint8_t h[32];int fd=open(path,O_RDONLY|O_CLOEXEC);if(fd<0)return -1;size_t got=0;while(got<sizeof h){ssize_t r=read(fd,h+got,sizeof h-got);if(r<0){if(errno==EINTR)continue;close(fd);return -1;}if(!r){close(fd);return -1;}got+=(size_t)r;}close(fd);if(memcmp(h,"DARCOBJ1",8)||darc_rd_u16(h+10)!=0||darc_rd_u32(h+28)!=darc_crc32c(h+8,20)||h[8]<1||h[8]>5||h[9]>1)return -1;out->type=h[8];out->codec=h[9];out->uncomp_len=darc_rd_u64(h+12);out->stored_len=darc_rd_u64(h+20);out->used=1;return 0;}
int darc_index_rebuild(const char*repo){char*root=darc_path_join(repo,"objects/sha256");if(!root)return DARC_E_IO;DarcRhEnt*arr=NULL;size_t n=0,cap=0;DIR*d=opendir(root);if(!d){free(root);return DARC_E_IO;}struct dirent*de;while((de=readdir(d))){if(strlen(de->d_name)!=2||de->d_name[0]=='.')continue;char*dir=darc_path_join(root,de->d_name);if(!dir)goto oom;DIR*dd=opendir(dir);if(!dd){free(dir);continue;}struct dirent*oe;while((oe=readdir(dd))){if(strlen(oe->d_name)!=62||oe->d_name[0]=='.')continue;char hex[65];memcpy(hex,de->d_name,2);memcpy(hex+2,oe->d_name,62);hex[64]=0;DarcRhEnt e;memset(&e,0,sizeof e);if(darc_hex_cid(hex,&e.cid)){continue;}char*p=darc_path_join(dir,oe->d_name);if(!p){closedir(dd);free(dir);goto oom;}if(read_header_fd(p,&e)){free(p);continue;}free(p);if(n==cap){size_t nc=cap?cap*2:128;DarcRhEnt*x=darc_realloc(arr,nc*sizeof*x);if(!x){closedir(dd);free(dir);goto oom;}arr=x;cap=nc;}arr[n++]=e;}closedir(dd);free(dir);}closedir(d);free(root);if(n>1)qsort(arr,n,sizeof*arr,entcmp);for(size_t i=1;i<n;i++)if(!darc_cid_cmp(&arr[i-1].cid,&arr[i].cid)){free(arr);return DARC_E_CORRUPT;}DarcBuf b;darc_buf_init(&b);if(darc_buf_put(&b,"DARCIDX1",8)||darc_buf_u16(&b,1)||darc_buf_u16(&b,0)||darc_buf_u64(&b,(uint64_t)n))goto oom2;for(size_t i=0;i<n;i++){if(darc_buf_put(&b,arr[i].cid.b,32)||darc_buf_u8(&b,arr[i].type)||darc_buf_u8(&b,arr[i].codec)||darc_buf_u16(&b,0)||darc_buf_u64(&b,arr[i].stored_len)||darc_buf_u64(&b,arr[i].uncomp_len))goto oom2;}if(darc_buf_u32(&b,darc_crc32c(b.data,b.len)))goto oom2;char*p=darc_path_join(repo,"index/chunks.idx");if(!p)goto oom2;int rc=darc_atomic_write_checkpoint(p,b.data,b.len,0644,"index_before_publish")?DARC_E_IO:0;free(p);darc_buf_free(&b);free(arr);return rc;
oom2:darc_buf_free(&b);oom:if(d)closedir(d);free(root);free(arr);return DARC_E_IO;}
int darc_index_load(const char*repo,DarcRhMap*m){memset(m,0,sizeof*m);char*p=darc_path_join(repo,"index/chunks.idx");if(!p)return DARC_E_IO;DarcBuf b;if(darc_read_file(p,&b,256u*1024u*1024u)){free(p);return DARC_E_CORRUPT;}free(p);if(b.len<24||memcmp(b.data,"DARCIDX1",8)||darc_rd_u16(b.data+8)!=1||darc_rd_u16(b.data+10)!=0){darc_buf_free(&b);return DARC_E_CORRUPT;}uint64_t n=darc_rd_u64(b.data+12);if(n>SIZE_MAX/52||20+(size_t)n*52+4!=b.len||darc_rd_u32(b.data+b.len-4)!=darc_crc32c(b.data,b.len-4)){darc_buf_free(&b);return DARC_E_CORRUPT;}if(darc_rh_init(m,(size_t)n*2+8)){darc_buf_free(&b);return DARC_E_IO;}size_t o=20;DarcCid prev;int have=0;for(size_t i=0;i<(size_t)n;i++){DarcRhEnt e;memset(&e,0,sizeof e);memcpy(e.cid.b,b.data+o,32);o+=32;e.type=b.data[o++];e.codec=b.data[o++];if(darc_rd_u16(b.data+o)!=0||e.type<1||e.type>5||e.codec>1)goto bad;o+=2;e.stored_len=darc_rd_u64(b.data+o);o+=8;e.uncomp_len=darc_rd_u64(b.data+o);o+=8;if(have&&darc_cid_cmp(&prev,&e.cid)>=0)goto bad;prev=e.cid;have=1;if(darc_rh_put(m,&e))goto bad;}darc_buf_free(&b);return 0;bad:darc_buf_free(&b);darc_rh_free(m);return DARC_E_CORRUPT;}
